WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, CASE WHEN session_start_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_start_flag_tier, SUM(CASE WHEN status = 'SUCCESS' THEN amount ELSE 0 END) AS success_amount, MAX(paid_at) AS last_seen, ROUND(AVG(session_start_flag), 2) AS avg_session_start_flag, GROUPING_ID() AS grouping_level FROM sessionized GROUP BY CUBE (DATE_TRUNC('WEEK', paid_at), CASE WHEN session_start_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY week_start DESC NULLS LAST;
